import { open } from "@tauri-apps/plugin-dialog";
import { FolderGit2, FolderPlus, GitBranch, LoaderCircle, X } from "lucide-react";
import { FormEvent, useEffect, useRef, useState } from "react";

import {
  createWorktree,
  isTauriRuntime,
  listProjectBranches,
  registerProject,
  type LocalBranch,
  type RegisteredProject,
} from "../lib/tauri";
import type { Worktree } from "../lib/types";

const fieldClass =
  "h-8 w-full rounded-md border border-input bg-background px-2 text-xs text-foreground outline-none transition-colors placeholder:text-muted-foreground/45 focus:border-ring";

function checkIsTauri(): boolean {
  try {
    return Boolean(isTauriRuntime());
  } catch {
    return false;
  }
}

export function deriveWorkspaceId(folderPath: string, existingProjects: RegisteredProject[] = []): string {
  const normalized = folderPath.replace(/[/\\]+$/, "");
  const basename = normalized.split(/[/\\]/).pop() || "";
  let baseId = basename.replace(/[\s/\\\x00-\x1f\x7f]+/g, "-").replace(/^-+/, "");
  if (!baseId) {
    baseId = "project";
  }
  const existingIds = new Set(existingProjects.map((p) => p.workspaceId));
  if (!existingIds.has(baseId)) {
    return baseId;
  }
  let index = 2;
  while (existingIds.has(`${baseId}-${index}`)) {
    index++;
  }
  return `${baseId}-${index}`;
}

type AddProjectDialogProps = {
  projects?: RegisteredProject[];
  onClose: () => void;
  onRegistered: (project: RegisteredProject) => void;
};

export function AddProjectDialog({ projects = [], onClose, onRegistered }: AddProjectDialogProps) {
  const [workspaceId, setWorkspaceId] = useState("");
  const [repoPath, setRepoPath] = useState("");
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const onRegisteredRef = useRef(onRegistered);
  onRegisteredRef.current = onRegistered;
  const projectsRef = useRef(projects);
  projectsRef.current = projects;

  const pickerOpenedRef = useRef(false);
  const isTauri = checkIsTauri();

  useEffect(() => {
    if (!isTauri || pickerOpenedRef.current) return;
    pickerOpenedRef.current = true;
    let alive = true;
    void open({
      directory: true,
      multiple: false,
      title: "Add Project",
    })
      .then((selected) => {
        if (!alive) return;
        if (typeof selected === "string" && selected.length > 0) {
          setSelectedPath(selected);
        } else {
          onCloseRef.current();
        }
      })
      .catch((cause) => {
        console.error(cause);
        if (!alive) return;
        const message = cause instanceof Error ? cause.message : String(cause);
        setError(message || "Could not open folder picker.");
      });
    return () => {
      alive = false;
    };
  }, [isTauri]);

  if (isTauri && selectedPath) {
    const handleConfirm = async () => {
      if (submitting || !selectedPath) return;
      setSubmitting(true);
      setError(null);
      const derivedId = deriveWorkspaceId(selectedPath, projectsRef.current);
      try {
        const project = await registerProject({ workspaceId: derivedId, repoPath: selectedPath });
        onRegisteredRef.current(project);
        onCloseRef.current();
      } catch (cause) {
        setError(cause instanceof Error ? cause.message : "Could not register this project.");
      } finally {
        setSubmitting(false);
      }
    };

    return (
      <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/45 p-6" role="presentation">
        <div
          role="dialog"
          aria-label="Add Project"
          className="w-full max-w-[420px] overflow-hidden rounded-lg border border-border bg-card shadow-2xl"
        >
          <div className="flex h-9 items-center border-b border-border px-3">
            <FolderGit2 className="mr-2 size-3.5 text-muted-foreground" />
            <h2 className="text-[13px] font-medium">Add Project</h2>
            <button
              type="button"
              aria-label="Close Add Project"
              disabled={submitting}
              className="ml-auto rounded p-1 text-muted-foreground hover:bg-accent hover:text-foreground disabled:opacity-45"
              onClick={() => onCloseRef.current()}
            >
              <X className="size-3.5" />
            </button>
          </div>
          <div className="space-y-3 p-3">
            <p className="text-xs text-muted-foreground">
              Add this folder as a separate Orca project.
            </p>
            <div className="rounded-md border border-border/70 bg-muted/35 px-3 py-2 text-xs">
              <div className="break-all font-mono text-muted-foreground">{selectedPath}</div>
            </div>
            {error ? <p className="text-xs text-destructive">{error}</p> : null}
          </div>
          <div className="flex justify-end gap-2 border-t border-border px-3 py-2">
            <button
              type="button"
              disabled={submitting}
              className="h-7 rounded-md border border-border px-2.5 text-xs text-muted-foreground hover:bg-accent disabled:opacity-45"
              onClick={() => onCloseRef.current()}
            >
              Cancel
            </button>
            <button
              type="button"
              disabled={submitting || !selectedPath}
              onClick={handleConfirm}
              className="inline-flex h-7 items-center gap-1.5 rounded-md bg-primary px-3 text-xs font-medium text-primary-foreground disabled:opacity-45"
            >
              {submitting ? (
                <LoaderCircle className="size-3.5 animate-spin" />
              ) : (
                <FolderPlus className="size-3.5" />
              )}
              Add Project
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (isTauri && !error) {
    return null;
  }

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    const trimmedWorkspaceId = workspaceId.trim();
    const trimmedPath = repoPath.trim();
    if (!trimmedWorkspaceId || !trimmedPath || submitting) return;
    setSubmitting(true);
    setError(null);
    try {
      const project = await registerProject({ workspaceId: trimmedWorkspaceId, repoPath: trimmedPath });
      onRegisteredRef.current(project);
      onCloseRef.current();
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Could not register this project.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/45 p-6" role="presentation">
      <form
        aria-label="Add Project"
        className="w-full max-w-[420px] overflow-hidden rounded-lg border border-border bg-card shadow-2xl"
        onSubmit={submit}
      >
        <div className="flex h-9 items-center border-b border-border px-3">
          <FolderGit2 className="mr-2 size-3.5 text-muted-foreground" />
          <h2 className="text-[13px] font-medium">Add Project</h2>
          <button
            type="button"
            aria-label="Close Add Project"
            className="ml-auto rounded p-1 text-muted-foreground hover:bg-accent hover:text-foreground"
            onClick={() => onCloseRef.current()}
          >
            <X className="size-3.5" />
          </button>
        </div>
        <div className="space-y-3 p-3">
          <label className="block space-y-1 text-[11px] text-muted-foreground">
            <span>Workspace id</span>
            <input
              aria-label="Workspace id"
              className={fieldClass}
              value={workspaceId}
              onChange={(event) => setWorkspaceId(event.target.value)}
              placeholder="my-project"
              autoFocus
            />
          </label>
          <label className="block space-y-1 text-[11px] text-muted-foreground">
            <span>Repository path</span>
            <input
              aria-label="Repository path"
              className={fieldClass}
              value={repoPath}
              onChange={(event) => setRepoPath(event.target.value)}
              placeholder="/path/to/repository"
            />
          </label>
          {error ? <p className="text-[11px] text-destructive">{error}</p> : null}
        </div>
        <div className="flex justify-end gap-2 border-t border-border px-3 py-2">
          <button type="button" className="h-7 rounded-md px-2.5 text-xs text-muted-foreground hover:bg-accent" onClick={() => onCloseRef.current()}>
            Cancel
          </button>
          <button
            type="submit"
            disabled={submitting || !workspaceId.trim() || !repoPath.trim()}
            className="h-7 rounded-md bg-primary px-3 text-xs font-medium text-primary-foreground disabled:opacity-45"
          >
            Add Project
          </button>
        </div>
      </form>
    </div>
  );
}

type AddWorktreeDialogProps = {
  project: RegisteredProject;
  onClose: () => void;
  onCreated: (worktree: Worktree) => void | Promise<void>;
};

export function AddWorktreeDialog({ project, onClose, onCreated }: AddWorktreeDialogProps) {
  const [branches, setBranches] = useState<LocalBranch[]>([]);
  const [baseRef, setBaseRef] = useState("");
  const [slug, setSlug] = useState("");
  const [loadingBranches, setLoadingBranches] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    setLoadingBranches(true);
    setError(null);
    void listProjectBranches(project.workspaceId)
      .then((items) => {
        if (!alive) return;
        setBranches(items);
        const preferred = items.find((branch) => branch.isCurrent) ?? items[0];
        setBaseRef(preferred?.name ?? "");
      })
      .catch((cause) => {
        if (!alive) return;
        setError(cause instanceof Error ? cause.message : "Could not load local branches.");
      })
      .finally(() => {
        if (alive) setLoadingBranches(false);
      });
    return () => {
      alive = false;
    };
  }, [project.workspaceId]);

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    const trimmedSlug = slug.trim();
    if (!trimmedSlug || !baseRef || submitting) return;
    setSubmitting(true);
    setError(null);
    try {
      const worktree = await createWorktree({
        workspaceId: project.workspaceId,
        worktree: { wsId: project.workspaceId, slug: trimmedSlug },
        baseRef,
      });
      await onCreated(worktree);
      onClose();
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Could not create the worktree.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/45 p-6" role="presentation">
      <form
        aria-label="Add Worktree"
        className="w-full max-w-[420px] overflow-hidden rounded-lg border border-border bg-card shadow-2xl"
        onSubmit={submit}
      >
        <div className="flex h-9 items-center border-b border-border px-3">
          <GitBranch className="mr-2 size-3.5 text-muted-foreground" />
          <h2 className="min-w-0 flex-1 truncate text-[13px] font-medium">Add Worktree · {project.workspaceId}</h2>
          <button
            type="button"
            aria-label="Close Add Worktree"
            className="rounded p-1 text-muted-foreground hover:bg-accent hover:text-foreground"
            onClick={onClose}
          >
            <X className="size-3.5" />
          </button>
        </div>
        <div className="space-y-3 p-3">
          <label className="block space-y-1 text-[11px] text-muted-foreground">
            <span>Worktree slug</span>
            <input
              aria-label="Worktree slug"
              className={fieldClass}
              value={slug}
              onChange={(event) => setSlug(event.target.value)}
              placeholder="feature-ui"
              autoFocus
            />
          </label>
          <label className="block space-y-1 text-[11px] text-muted-foreground">
            <span>Base branch</span>
            <select
              aria-label="Base branch"
              className={fieldClass}
              value={baseRef}
              disabled={loadingBranches || branches.length === 0}
              onChange={(event) => setBaseRef(event.target.value)}
            >
              {branches.map((branch) => (
                <option key={branch.name} value={branch.name}>
                  {branch.name}{branch.isCurrent ? " (current)" : ""}
                </option>
              ))}
            </select>
          </label>
          <p className="truncate text-[10px] text-muted-foreground/70">{project.repoRoot}</p>
          {error ? <p className="text-[11px] text-destructive">{error}</p> : null}
        </div>
        <div className="flex justify-end gap-2 border-t border-border px-3 py-2">
          <button type="button" className="h-7 rounded-md px-2.5 text-xs text-muted-foreground hover:bg-accent" onClick={onClose}>
            Cancel
          </button>
          <button
            type="submit"
            disabled={submitting || loadingBranches || !slug.trim() || !baseRef}
            className="h-7 rounded-md bg-primary px-3 text-xs font-medium text-primary-foreground disabled:opacity-45"
          >
            Create Worktree
          </button>
        </div>
      </form>
    </div>
  );
}

import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const native = vi.hoisted(() => ({
  isTauriRuntime: vi.fn(),
  registerProject: vi.fn(),
  listProjectBranches: vi.fn(),
  createWorktree: vi.fn(),
}));

const dialog = vi.hoisted(() => ({
  open: vi.fn(),
}));

vi.mock("../lib/tauri", () => native);
vi.mock("@tauri-apps/plugin-dialog", () => dialog);

import { AddProjectDialog, AddWorktreeDialog, deriveWorkspaceId } from "./ProjectDialogs";

afterEach(cleanup);
beforeEach(() => {
  native.isTauriRuntime.mockReset();
  native.registerProject.mockReset();
  native.listProjectBranches.mockReset();
  native.createWorktree.mockReset();
  dialog.open.mockReset();
});

describe("deriveWorkspaceId helper", () => {
  it("derives workspaceId by slugifying basename and deduplicating", () => {
    expect(deriveWorkspaceId("/Users/dev/my-project")).toBe("my-project");
    expect(deriveWorkspaceId("/Users/dev/my-project/")).toBe("my-project");
    expect(deriveWorkspaceId("/Users/dev/My Cool App 123")).toBe("My-Cool-App-123");
    expect(deriveWorkspaceId("/Users/dev/---leading-dash")).toBe("leading-dash");
    expect(deriveWorkspaceId("///")).toBe("project");

    const existing = [
      { workspaceId: "my-project", repoRoot: "/a" },
      { workspaceId: "my-project-2", repoRoot: "/b" },
    ];
    expect(deriveWorkspaceId("/Users/dev/my-project", existing)).toBe("my-project-3");
  });
});

describe("AddProjectDialog Tauri flow", () => {
  it("closes dialog when picker is cancelled (null result)", async () => {
    native.isTauriRuntime.mockReturnValue(true);
    dialog.open.mockResolvedValue(null);
    const onClose = vi.fn();

    render(<AddProjectDialog onClose={onClose} onRegistered={vi.fn()} />);

    await waitFor(() =>
      expect(dialog.open).toHaveBeenCalledWith({
        directory: true,
        multiple: false,
        title: "Add Project",
      }),
    );
    await waitFor(() => expect(onClose).toHaveBeenCalled());
  });

  it("shows confirmation dialog with the selected path", async () => {
    native.isTauriRuntime.mockReturnValue(true);
    dialog.open.mockResolvedValue("/Users/dev/orca-project");
    const onClose = vi.fn();

    render(<AddProjectDialog onClose={onClose} onRegistered={vi.fn()} />);

    await waitFor(() => expect(screen.getByText("/Users/dev/orca-project")).toBeInTheDocument());
    expect(screen.getByText("Add this folder as a separate Orca project.")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Add Project" })).toBeInTheDocument();
  });

  it("submits with derived slugified id from basename and calls registerProject + onRegistered", async () => {
    native.isTauriRuntime.mockReturnValue(true);
    dialog.open.mockResolvedValue("/Users/dev/My Awesome Project");
    const registered = { workspaceId: "My-Awesome-Project", repoRoot: "/Users/dev/My Awesome Project" };
    native.registerProject.mockResolvedValue(registered);
    const onRegistered = vi.fn();
    const onClose = vi.fn();

    render(<AddProjectDialog onClose={onClose} onRegistered={onRegistered} />);

    await waitFor(() => expect(screen.getByText("/Users/dev/My Awesome Project")).toBeInTheDocument());
    fireEvent.click(screen.getByRole("button", { name: "Add Project" }));

    await waitFor(() =>
      expect(native.registerProject).toHaveBeenCalledWith({
        workspaceId: "My-Awesome-Project",
        repoPath: "/Users/dev/My Awesome Project",
      }),
    );
    expect(onRegistered).toHaveBeenCalledWith(registered);
    expect(onClose).toHaveBeenCalled();
  });

  it("appends -2 suffix when derived workspaceId conflicts with existing projects", async () => {
    native.isTauriRuntime.mockReturnValue(true);
    dialog.open.mockResolvedValue("/Users/dev/existing-app");
    const existing = [{ workspaceId: "existing-app", repoRoot: "/other/path/existing-app" }];
    const registered = { workspaceId: "existing-app-2", repoRoot: "/Users/dev/existing-app" };
    native.registerProject.mockResolvedValue(registered);
    const onRegistered = vi.fn();
    const onClose = vi.fn();

    render(<AddProjectDialog projects={existing} onClose={onClose} onRegistered={onRegistered} />);

    await waitFor(() => expect(screen.getByText("/Users/dev/existing-app")).toBeInTheDocument());
    fireEvent.click(screen.getByRole("button", { name: "Add Project" }));

    await waitFor(() =>
      expect(native.registerProject).toHaveBeenCalledWith({
        workspaceId: "existing-app-2",
        repoPath: "/Users/dev/existing-app",
      }),
    );
    expect(onRegistered).toHaveBeenCalledWith(registered);
    expect(onClose).toHaveBeenCalled();
  });

  it("keeps dialog mounted with manual form and shows error when picker is rejected", async () => {
    const consoleSpy = vi.spyOn(console, "error").mockImplementation(() => {});
    native.isTauriRuntime.mockReturnValue(true);
    dialog.open.mockRejectedValue(new Error("Native dialog capability error"));
    const onClose = vi.fn();
    const onRegistered = vi.fn();
    native.registerProject.mockResolvedValue({ workspaceId: "manual-project", repoRoot: "/custom/path" });

    render(<AddProjectDialog onClose={onClose} onRegistered={onRegistered} />);

    await waitFor(() => expect(screen.getByText("Native dialog capability error")).toBeInTheDocument());
    expect(screen.getByLabelText("Workspace id")).toBeInTheDocument();
    expect(screen.getByLabelText("Repository path")).toBeInTheDocument();
    expect(onClose).not.toHaveBeenCalled();
    expect(consoleSpy).toHaveBeenCalled();
    consoleSpy.mockRestore();

    fireEvent.change(screen.getByLabelText("Workspace id"), { target: { value: "manual-project" } });
    fireEvent.change(screen.getByLabelText("Repository path"), { target: { value: "/custom/path" } });
    fireEvent.click(screen.getByRole("button", { name: "Add Project" }));

    await waitFor(() =>
      expect(native.registerProject).toHaveBeenCalledWith({
        workspaceId: "manual-project",
        repoPath: "/custom/path",
      }),
    );
    expect(onRegistered).toHaveBeenCalledWith({ workspaceId: "manual-project", repoRoot: "/custom/path" });
    expect(onClose).toHaveBeenCalled();
  });

  it("does not re-invoke picker when parent re-renders with new onClose identity", async () => {
    native.isTauriRuntime.mockReturnValue(true);
    dialog.open.mockReturnValue(new Promise(() => {}));
    const onClose1 = vi.fn();

    const { rerender } = render(<AddProjectDialog onClose={onClose1} onRegistered={vi.fn()} />);

    expect(dialog.open).toHaveBeenCalledTimes(1);

    const onClose2 = vi.fn();
    rerender(<AddProjectDialog onClose={onClose2} onRegistered={vi.fn()} />);

    expect(dialog.open).toHaveBeenCalledTimes(1);
  });
});

describe("AddProjectDialog non-Tauri fallback flow", () => {
  it("keeps manual form in non-Tauri runtime and registers project", async () => {
    native.isTauriRuntime.mockReturnValue(false);
    const onRegistered = vi.fn();
    native.registerProject.mockResolvedValue({ workspaceId: "orca-lite", repoRoot: "/repo/orca-lite" });

    render(<AddProjectDialog onClose={vi.fn()} onRegistered={onRegistered} />);
    expect(screen.getByLabelText("Workspace id")).toBeInTheDocument();
    expect(screen.getByLabelText("Repository path")).toBeInTheDocument();

    fireEvent.change(screen.getByLabelText("Workspace id"), { target: { value: "orca-lite" } });
    fireEvent.change(screen.getByLabelText("Repository path"), { target: { value: "/repo/orca-lite" } });
    fireEvent.click(screen.getByRole("button", { name: "Add Project" }));

    await waitFor(() =>
      expect(native.registerProject).toHaveBeenCalledWith({
        workspaceId: "orca-lite",
        repoPath: "/repo/orca-lite",
      }),
    );
    expect(onRegistered).toHaveBeenCalledWith({ workspaceId: "orca-lite", repoRoot: "/repo/orca-lite" });
  });
  it("uses neutral placeholder for workspace id input", () => {
    native.isTauriRuntime.mockReturnValue(false);
    render(<AddProjectDialog onClose={vi.fn()} onRegistered={vi.fn()} />);
    const input = screen.getByLabelText("Workspace id");
    expect(input).toHaveAttribute("placeholder", "my-project");
  });
});

describe("AddWorktreeDialog flow", () => {
  it("loads local branches and uses a real branch dropdown for Add Worktree", async () => {
    native.listProjectBranches.mockResolvedValue([
      { name: "develop", isCurrent: false },
      { name: "main", isCurrent: true },
    ]);
    native.createWorktree.mockResolvedValue({ path: "/repo/worktrees/feature-ui" });
    const onCreated = vi.fn();

    render(
      <AddWorktreeDialog
        project={{ workspaceId: "orca-lite", repoRoot: "/repo/orca-lite" }}
        onClose={vi.fn()}
        onCreated={onCreated}
      />,
    );

    await waitFor(() => expect(native.listProjectBranches).toHaveBeenCalledWith("orca-lite"));
    const branch = screen.getByRole("combobox", { name: "Base branch" });
    expect(branch.tagName).toBe("SELECT");
    expect(screen.getByRole("option", { name: "main (current)" })).toBeInTheDocument();
    expect(screen.queryByRole("textbox", { name: "Base branch" })).not.toBeInTheDocument();

    fireEvent.change(screen.getByLabelText("Worktree slug"), { target: { value: "feature-ui" } });
    fireEvent.change(branch, { target: { value: "develop" } });
    fireEvent.click(screen.getByRole("button", { name: "Create Worktree" }));

    await waitFor(() =>
      expect(native.createWorktree).toHaveBeenCalledWith({
        workspaceId: "orca-lite",
        worktree: { wsId: "orca-lite", slug: "feature-ui" },
        baseRef: "develop",
      }),
    );
    expect(onCreated).toHaveBeenCalled();
  });
});

